    45  type IOURequestStepDistanceOnyxProps = {
    46      /** backup version of the original transaction  */
    47      transactionBackup: OnyxEntry<OnyxTypes.Transaction>;
    48
    49      /** The policy which the user has access to and which the report is tied to */
    50      policy: OnyxEntry<OnyxTypes.Policy>;
    51
    52      /** Personal details of all users */
    53      personalDetails: OnyxEntry<OnyxTypes.PersonalDetailsList>;
    54
    55      /** Whether the confirmation step should be skipped */
    56      skipConfirmation: OnyxEntry<boolean>;
    57  };
    58
    59  type IOURequestStepDistanceProps = IOURequestStepDistanceOnyxProps &
    60      WithCurrentUserPersonalDetailsProps &
    61      WithWritableReportOrNotFoundProps<typeof SCREENS.MONEY_REQUEST.STEP_DISTANCE | typeof SCREENS.MONEY_REQUEST.CREATE> & {
    62          /** The transaction object being modified in Onyx */
    63          transaction: OnyxEntry<OnyxTypes.Transaction>;
    64      };
    65
    66  function IOURequestStepDistance({
    67      report,
    68      policy,
    69      route: {
    70          params: {action, iouType, reportID, transactionID, backTo},
    71      },
    72      transaction,
    73      transactionBackup,
    74      personalDetails,
    75      currentUserPersonalDetails,
    76      skipConfirmation,
    77  }: IOURequestStepDistanceProps) {
    78      const styles = useThemeStyles();
    79      const {isOffline} = useNetwork();
    80      const {translate} = useLocalize();
    81      const [reportNameValuePairs] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT_NAME_VALUE_PAIRS}${report?.reportID ?? -1}`);
    82
    83      const [optimisticWaypoints, setOptimisticWaypoints] = useState<WaypointCollection | null>(null);
    84      const waypoints = useMemo(
    85          () =>
    86              optimisticWaypoints ??
    87              transaction?.comment?.waypoints ?? {
    88                  waypoint0: {keyForList: 'start_waypoint'},
    89                  waypoint1: {keyForList: 'stop_waypoint'},
    90              },
    91          [optimisticWaypoints, transaction],
    92      );
    93      const {shouldFetchRoute, validatedWaypoints} = useFetchRoute(transaction, waypoints, action);
    94      const waypointsList = Object.keys(waypoints);
    95      const previousWaypoints = usePrevious(waypoints);
    96      const numberOfWaypoints = Object.keys(waypoints).length;
    97      const numberOfPreviousWaypoints = Object.keys(previousWaypoints).length;
    98      const scrollViewRef = useRef<RNScrollView>(null);
    99      const isLoadingRoute = transaction?.comment?.isLoading ?? false;
   100      const isLoading = transaction?.isLoading ?? false;
   101      const hasRouteError = !!transaction?.errorFields?.route;
   102      const [shouldShowAtLeastTwoDifferentWaypointsError, setShouldShowAtLeastTwoDifferentWaypointsError] = useState(false);
   103      const isWaypointEmpty = (waypoint?: Waypoint) => {
   104          if (!waypoint) {
   105              return true;
   106          }
   107          const {keyForList, ...waypointWithoutKey} = waypoint;
   108          return isEmpty(waypointWithoutKey);
   109      };
   110      const nonEmptyWaypointsCount = useMemo(() => Object.keys(waypoints).filter((key) => !isWaypointEmpty(waypoints[key])).length, [waypoints]);
   111
   112      const duplicateWaypointsError = useMemo(
   113          () => nonEmptyWaypointsCount >= 2 && Object.keys(validatedWaypoints).length !== nonEmptyWaypointsCount,
   114          [nonEmptyWaypointsCount, validatedWaypoints],
   115      );
   116      const atLeastTwoDifferentWaypointsError = useMemo(() => Object.keys(validatedWaypoints).length < 2, [validatedWaypoints]);
   117      const isEditing = action === CONST.IOU.ACTION.EDIT;
   118      const transactionWasSaved = useRef(false);
   119      const isCreatingNewRequest = !(backTo || isEditing);
   120      const [recentWaypoints, {status: recentWaypointsStatus}] = useOnyx(ONYXKEYS.NVP_RECENT_WAYPOINTS);
   121      const iouRequestType = TransactionUtils.getRequestType(transaction);
   122      const customUnitRateID = TransactionUtils.getRateID(transaction);
   123
   124      // For quick button actions, we'll skip the confirmation page unless the report is archived or this is a workspace
   125      // request and the workspace requires a category or a tag
   126      const shouldSkipConfirmation: boolean = useMemo(() => {
   127          if (!skipConfirmation || !report?.reportID) {
   128              return false;
   129          }
   130
   131          return (
   132              !ReportUtils.isArchivedRoom(report, reportNameValuePairs) && !(ReportUtils.isPolicyExpenseChat(report) && ((policy?.requiresCategory ?? false) || (policy?.requiresTag ?? false)))
   133          );
   134      }, [report, skipConfirmation, policy, reportNameValuePairs]);
   135      let buttonText = !isCreatingNewRequest ? translate('common.save') : translate('common.next');
   136      if (shouldSkipConfirmation) {
   137          if (iouType === CONST.IOU.TYPE.SPLIT) {
   138              buttonText = translate('iou.split');
   139          } else if (iouType === CONST.IOU.TYPE.TRACK) {
   140              buttonText = translate('iou.trackExpense');
   141          } else {
   142              buttonText = translate('iou.submitExpense');
   143          }
   144      }
   145
   146      useEffect(() => {
   147          if (iouRequestType !== CONST.IOU.REQUEST_TYPE.DISTANCE || isOffline || recentWaypointsStatus === 'loading' || recentWaypoints !== undefined) {
   148              return;
   149          }
   150
   151          // Only load the recent waypoints if they have been read from Onyx as undefined
   152          // If the account doesn't have recent waypoints they will be returned as an empty array
   153          TransactionAction.openDraftDistanceExpense();
   154      }, [iouRequestType, recentWaypointsStatus, recentWaypoints, isOffline]);
   155
   156      useEffect(() => {
   157          MapboxToken.init();
   158          return MapboxToken.stop;
   159      }, []);
   160
   161      useEffect(() => {
   162          if (numberOfWaypoints <= numberOfPreviousWaypoints) {
   163              return;
   164          }
   165          scrollViewRef.current?.scrollToEnd({animated: true});
   166      }, [numberOfPreviousWaypoints, numberOfWaypoints]);
   167
   168      useEffect(() => {
   169          if (nonEmptyWaypointsCount >= 2 && (duplicateWaypointsError || atLeastTwoDifferentWaypointsError || hasRouteError || isLoadingRoute || isLoading)) {
   170              return;
   171          }
   172          setShouldShowAtLeastTwoDifferentWaypointsError(false);
   173      }, [atLeastTwoDifferentWaypointsError, duplicateWaypointsError, hasRouteError, isLoading, isLoadingRoute, nonEmptyWaypointsCount, transaction]);
   174
   175      // This effect runs when the component is mounted and unmounted. It's purpose is to be able to properly
   176      // discard changes if the user cancels out of making any changes. This is accomplished by backing up the
   177      // original transaction, letting the user modify the current transaction, and then if the user ever
   178      // cancels out of the modal without saving changes, the original transaction is restored from the backup.
   179      useEffect(() => {
   180          if (isCreatingNewRequest) {
   181              return () => {};
   182          }
   183
   184          // On mount, create the backup transaction.
   185          TransactionEdit.createBackupTransaction(transaction);
   186
   187          return () => {
   188              // If the user cancels out of the modal without without saving changes, then the original transaction
   189              // needs to be restored from the backup so that all changes are removed.
   190              if (transactionWasSaved.current) {
   191                  TransactionEdit.removeBackupTransaction(transaction?.transactionID ?? '-1');
   192                  return;
   193              }
   194              TransactionEdit.restoreOriginalTransactionFromBackup(transaction?.transactionID ?? '-1', IOUUtils.shouldUseTransactionDraft(action));
   195          };
   196          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   197      }, []);
   198
   199      const navigateBack = useCallback(() => {
   200          Navigation.goBack(backTo);
   201      }, [backTo]);
   202
   203      /**
   204       * Takes the user to the page for editing a specific waypoint
   205       * @param index of the waypoint to edit
   206       */
   207      const navigateToWaypointEditPage = useCallback(
   208          (index: number) => {
   209              Navigation.navigate(
   210                  ROUTES.MONEY_REQUEST_STEP_WAYPOINT.getRoute(action, CONST.IOU.TYPE.SUBMIT, transactionID, report?.reportID ?? reportID, index.toString(), Navigation.getActiveRoute()),
   211              );
   212          },
   213          [action, transactionID, report?.reportID, reportID],
   214      );
   215
   216      const navigateToParticipantPage = useCallback(() => {
   217          switch (iouType) {
   218              case CONST.IOU.TYPE.REQUEST:
   219                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_PARTICIPANTS.getRoute(CONST.IOU.TYPE.SUBMIT, transactionID, reportID));
   220                  break;
   221              case CONST.IOU.TYPE.SEND:
   222                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_PARTICIPANTS.getRoute(CONST.IOU.TYPE.PAY, transactionID, reportID));
   223                  break;
   224              default:
   225                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_PARTICIPANTS.getRoute(iouType, transactionID, reportID));
   226          }
   227      }, [iouType, reportID, transactionID]);
   228
   229      const navigateToConfirmationPage = useCallback(() => {
   230          switch (iouType) {
   231              case CONST.IOU.TYPE.REQUEST:
   232                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_CONFIRMATION.getRoute(CONST.IOU.ACTION.CREATE, CONST.IOU.TYPE.SUBMIT, transactionID, reportID));
   233                  break;
   234              case CONST.IOU.TYPE.SEND:
   235                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_CONFIRMATION.getRoute(CONST.IOU.ACTION.CREATE, CONST.IOU.TYPE.PAY, transactionID, reportID));
   236                  break;
   237              default:
   238                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_CONFIRMATION.getRoute(CONST.IOU.ACTION.CREATE, iouType, transactionID, reportID));
   239          }
   240      }, [iouType, reportID, transactionID]);
   241
   242      const navigateToNextStep = useCallback(() => {
   243          if (backTo) {
   244              Navigation.goBack(backTo);
   245              return;
   246          }
   247
   248          // If a reportID exists in the report object, it's because the user started this flow from using the + button in the composer
   249          // inside a report. In this case, the participants can be automatically assigned from the report and the user can skip the participants step and go straight
   250          // to the confirm step.
   251          if (report?.reportID && !ReportUtils.isArchivedRoom(report, reportNameValuePairs)) {
   252              const selectedParticipants = IOU.setMoneyRequestParticipantsFromReport(transactionID, report);
   253              const participants = selectedParticipants.map((participant) => {
   254                  const participantAccountID = participant?.accountID ?? -1;
   255                  return participantAccountID ? OptionsListUtils.getParticipantsOption(participant, personalDetails) : OptionsListUtils.getReportOption(participant);
   256              });
   257              if (shouldSkipConfirmation) {
   258                  if (iouType === CONST.IOU.TYPE.SPLIT) {
   259                      IOU.splitBill({
   260                          participants,
   261                          currentUserLogin: currentUserPersonalDetails.login ?? '',
   262                          currentUserAccountID: currentUserPersonalDetails.accountID,
   263                          amount: 0,
   264                          comment: '',
   265                          currency: transaction?.currency ?? 'USD',
   266                          merchant: translate('iou.fieldPending'),
   267                          created: transaction?.created ?? '',
   268                          category: '',
   269                          tag: '',
   270                          billable: false,
   271                          iouRequestType,
   272                          existingSplitChatReportID: report?.reportID,
   273                      });
   274                      return;
   275                  }
   276                  IOU.setMoneyRequestPendingFields(transactionID, {waypoints: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD});
   277                  IOU.setMoneyRequestMerchant(transactionID, translate('iou.fieldPending'), false);
   278                  if (iouType === CONST.IOU.TYPE.TRACK) {
   279                      IOU.trackExpense(
   280                          report,
   281                          0,
   282                          transaction?.currency ?? 'USD',
   283                          transaction?.created ?? '',
   284                          translate('iou.fieldPending'),
   285                          currentUserPersonalDetails.login,
   286                          currentUserPersonalDetails.accountID,
   287                          participants[0],
   288                          '',
   289                          {},
   290                          '',
   291                          '',
   292                          '',
   293                          0,
   294                          false,
   295                          policy,
   296                          undefined,
   297                          undefined,
   298                          undefined,
   299                          TransactionUtils.getValidWaypoints(waypoints, true),
   300                          undefined,
   301                          undefined,
   302                          undefined,
   303                          undefined,
   304                          customUnitRateID,
   305                      );
   306                      return;
   307                  }
   308
   309                  IOU.createDistanceRequest(
   310                      report,
   311                      participants,
   312                      '',
   313                      transaction?.created ?? '',
   314                      '',
   315                      '',
   316                      '',
   317                      0,
   318                      0,
   319                      transaction?.currency ?? 'USD',
   320                      translate('iou.fieldPending'),
   321                      !!policy?.defaultBillable,
   322                      TransactionUtils.getValidWaypoints(waypoints, true),
   323                      undefined,
   324                      undefined,
   325                      undefined,
   326                      DistanceRequestUtils.getCustomUnitRateID(report.reportID),
   327                      currentUserPersonalDetails.login ?? '',
   328                      currentUserPersonalDetails.accountID,
   329                      transaction?.splitShares,
   330                      iouType,
   331                  );
   332                  return;
   333              }
   334              IOU.setMoneyRequestParticipantsFromReport(transactionID, report);
   335              navigateToConfirmationPage();
   336              return;
   337          }
   338
   339          // If there was no reportID, then that means the user started this flow from the global menu
   340          // and an optimistic reportID was generated. In that case, the next step is to select the participants for this expense.
   341          navigateToParticipantPage();
   342      }, [
   343          report,
   344          iouType,
   345          transactionID,
   346          backTo,
   347          waypoints,
   348          currentUserPersonalDetails,
   349          personalDetails,
   350          shouldSkipConfirmation,
   351          transaction,
   352          translate,
   353          navigateToParticipantPage,
   354          navigateToConfirmationPage,
   355          policy,
   356          iouRequestType,
   357          reportNameValuePairs,
   358          customUnitRateID,
   359      ]);
   360
   361      const getError = () => {
   362          // Get route error if available else show the invalid number of waypoints error.
   363          if (hasRouteError) {
   364              return ErrorUtils.getLatestErrorField(transaction, 'route');
   365          }
   366          if (duplicateWaypointsError) {
   367              return {duplicateWaypointsError: translate('iou.error.duplicateWaypointsErrorMessage')} as Errors;
   368          }
   369          if (atLeastTwoDifferentWaypointsError) {
   370              return {atLeastTwoDifferentWaypointsError: translate('iou.error.atLeastTwoDifferentWaypoints')} as Errors;
   371          }
   372          return {};
   373      };
   374
   375      type DataParams = {
   376          data: string[];
   377      };
   378
   379      const updateWaypoints = useCallback(
   380          ({data}: DataParams) => {
   381              if (isEqual(waypointsList, data)) {
   382                  return;
   383              }
   384
   385              const newWaypoints: WaypointCollection = {};
   386              let emptyWaypointIndex = -1;
   387              data.forEach((waypoint, index) => {
   388                  newWaypoints[`waypoint${index}`] = waypoints[waypoint] ?? {};
   389                  // Find waypoint that BECOMES empty after dragging
   390                  if (isWaypointEmpty(newWaypoints[`waypoint${index}`]) && !isWaypointEmpty(waypoints[`waypoint${index}`])) {
   391                      emptyWaypointIndex = index;
   392                  }
   393              });
   394
   395              setOptimisticWaypoints(newWaypoints);
   396              Promise.all([
   397                  TransactionAction.removeWaypoint(transaction, emptyWaypointIndex.toString(), IOUUtils.shouldUseTransactionDraft(action)),
   398                  TransactionAction.updateWaypoints(transactionID, newWaypoints, IOUUtils.shouldUseTransactionDraft(action)),
   399              ]).then(() => {
   400                  setOptimisticWaypoints(null);
   401              });
   402          },
   403          [transactionID, transaction, waypoints, waypointsList, action],
   404      );
   405
   406      const submitWaypoints = useCallback(() => {
   407          // If there is any error or loading state, don't let user go to next page.
   408          if (duplicateWaypointsError || atLeastTwoDifferentWaypointsError || hasRouteError || isLoadingRoute || (!isEditing && isLoading)) {
   409              setShouldShowAtLeastTwoDifferentWaypointsError(true);
   410              return;
   411          }
   412          if (!isCreatingNewRequest) {
   413              transactionWasSaved.current = true;
   414          }
   415          if (isEditing) {
   416              // If nothing was changed, simply go to transaction thread
   417              // We compare only addresses because numbers are rounded while backup
   418              const oldWaypoints = transactionBackup?.comment?.waypoints ?? {};
   419              const oldAddresses = Object.fromEntries(Object.entries(oldWaypoints).map(([key, waypoint]) => [key, 'address' in waypoint ? waypoint.address : {}]));
   420              const addresses = Object.fromEntries(Object.entries(waypoints).map(([key, waypoint]) => [key, 'address' in waypoint ? waypoint.address : {}]));
   421              const hasRouteChanged = !isEqual(transactionBackup?.routes, transaction?.routes);
   422              if (isEqual(oldAddresses, addresses)) {
   423                  navigateBack();
   424                  return;
   425              }
   426              IOU.updateMoneyRequestDistance({
   427                  transactionID: transaction?.transactionID ?? '-1',
   428                  transactionThreadReportID: report?.reportID ?? '-1',
   429                  waypoints,
   430                  ...(hasRouteChanged ? {routes: transaction?.routes} : {}),
   431                  policy,
   432              });
   433              navigateBack();
   434              return;
   435          }
   436
   437          navigateToNextStep();
   438      }, [
   439          navigateBack,
   440          duplicateWaypointsError,
   441          atLeastTwoDifferentWaypointsError,
   442          hasRouteError,
   443          isLoadingRoute,
   444          isLoading,
   445          isCreatingNewRequest,
   446          isEditing,
   447          navigateToNextStep,
   448          transactionBackup,
   449          waypoints,
   450          transaction?.transactionID,
   451          transaction?.routes,
   452          report?.reportID,
   453          policy,
   454      ]);
   455
   456      const renderItem = useCallback(
   457          ({item, drag, isActive, getIndex}: RenderItemParams<string>) => (
   458              <DistanceRequestRenderItem
   459                  waypoints={waypoints}
   460                  item={item}
   461                  onSecondaryInteraction={drag}
   462                  isActive={isActive}
   463                  getIndex={getIndex}
   464                  onPress={navigateToWaypointEditPage}
   465                  disabled={isLoadingRoute}
   466              />
   467          ),
   468          [isLoadingRoute, navigateToWaypointEditPage, waypoints],
   469      );
   470
   471      return (
   472          <StepScreenWrapper
   473              headerTitle={translate('common.distance')}
   474              onBackButtonPress={navigateBack}
   475              testID={IOURequestStepDistance.displayName}
   476              shouldShowWrapper={!isCreatingNewRequest}
   477          >
   478              <>
   479                  <View style={styles.flex1}>
   480                      <DraggableList
   481                          data={waypointsList}
   482                          keyExtractor={(item) => (waypoints[item]?.keyForList ?? waypoints[item]?.address ?? '') + item}
   483                          shouldUsePortal
   484                          onDragEnd={updateWaypoints}
   485                          ref={scrollViewRef}
   486                          renderItem={renderItem}
   487                          ListFooterComponent={
   488                              <DistanceRequestFooter
   489                                  waypoints={waypoints}
   490                                  navigateToWaypointEditPage={navigateToWaypointEditPage}
   491                                  transaction={transaction}
   492                              />
   493                          }
   494                      />
   495                  </View>
   496                  <View style={[styles.w100, styles.pt2]}>
   497                      {/* Show error message if there is route error or there are less than 2 routes and user has tried submitting, */}
   498                      {((shouldShowAtLeastTwoDifferentWaypointsError && atLeastTwoDifferentWaypointsError) || duplicateWaypointsError || hasRouteError) && (
   499                          <DotIndicatorMessage
   500                              style={[styles.mh4, styles.mv3]}
   501                              messages={getError()}
   502                              type="error"
   503                          />
   504                      )}
   505                      <Button
   506                          success
   507                          allowBubble
   508                          pressOnEnter
   509                          large
   510                          style={[styles.w100, styles.mb4, styles.ph4, styles.flexShrink0]}
   511                          onPress={submitWaypoints}
   512                          text={buttonText}
   513                          isLoading={!isOffline && (isLoadingRoute || shouldFetchRoute || isLoading)}
   514                      />
   515                  </View>
   516              </>
   517          </StepScreenWrapper>
   518      );
   519  }
   520
   521  IOURequestStepDistance.displayName = 'IOURequestStepDistance';
   522
   523  const IOURequestStepDistanceWithOnyx = withOnyx<IOURequestStepDistanceProps, IOURequestStepDistanceOnyxProps>({
   524      transactionBackup: {
   525          key: ({route}) => {
   526              const transactionID = route.params.transactionID ?? -1;
   527              return `${ONYXKEYS.COLLECTION.TRANSACTION_BACKUP}${transactionID}`;
   528          },
   529      },
   530      policy: {
   531          key: ({report}) => `${ONYXKEYS.COLLECTION.POLICY}${report ? report?.policyID : '-1'}`,
   532      },
   533      personalDetails: {
   534          key: ONYXKEYS.PERSONAL_DETAILS_LIST,
   535      },
   536      skipConfirmation: {
   537          key: ({route}) => {
   538              const transactionID = route.params.transactionID ?? -1;
   539              return `${ONYXKEYS.COLLECTION.SKIP_CONFIRMATION}${transactionID}`;
   540          },
   541      },
   542  })(IOURequestStepDistance);
   543
   544  const IOURequestStepDistanceWithCurrentUserPersonalDetails = withCurrentUserPersonalDetails(IOURequestStepDistanceWithOnyx);
   545  // eslint-disable-next-line rulesdir/no-negated-variables
   546  const IOURequestStepDistanceWithWritableReportOrNotFound = withWritableReportOrNotFound(IOURequestStepDistanceWithCurrentUserPersonalDetails, true);
   547  // eslint-disable-next-line rulesdir/no-negated-variables
   548  const IOURequestStepDistanceWithFullTransactionOrNotFound = withFullTransactionOrNotFound(IOURequestStepDistanceWithWritableReportOrNotFound);
   549
   550  export default IOURequestStepDistanceWithFullTransactionOrNotFound;

